 if($action==='plant'){$company=(int)($_POST['company_id']??0);$n=field('name',180);if(!$company||$n===''||!C::row('SELECT id FROM companies WHERE id=? AND active=1',[$company]))fail('Azienda o nome impianto non valido.');C::exec('INSERT INTO plants(company_id,name) VALUES(?,?)',[$company,$n]);C::audit((int)$u['id'],'plant_created',(int)C::db()->lastInsertId());C::go('/?tab=accounts&saved=1');}
 if($action==='account'){$company=(int)($_POST['company_id']??0);$plant=(int)($_POST['plant_id']??0);$first=field('first_name',100);$last=field('last_name',100);$email=mb_strtolower(field('email',254));$password=(string)($_POST['password']??'');if(!$first||!$last||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12||!C::row('SELECT id FROM plants WHERE id=? AND company_id=? AND active=1',[$plant,$company]))fail('Controlla i dati: password di almeno 12 caratteri e impianto appartenente all’azienda.');C::db()->beginTransaction();try{C::exec("INSERT INTO users(company_id,first_name,last_name,email,password_hash,role) VALUES(?,?,?,?,?,'client')",[$company,$first,$last,$email,password_hash($password,PASSWORD_DEFAULT)]);$id=(int)C::db()->lastInsertId();C::exec('INSERT INTO user_plants(user_id,plant_id) VALUES(?,?)',[$id,$plant]);C::audit((int)$u['id'],'user_created',$id);C::db()->commit();}catch(Throwable $e){C::db()->rollBack();throw $e;}C::go('/?tab=accounts&saved=1');}
