 if($action==='upload'){$recipient=(int)($_POST['recipient_id']??0);$plant=(int)($_POST['plant_id']??0);$title=field('title',220);$r=C::row("SELECT u.id,u.company_id,u.email,u.first_name,u.last_name,p.name plant FROM users u JOIN user_plants up ON up.user_id=u.id JOIN plants p ON p.id=up.plant_id AND p.company_id=u.company_id AND p.active=1 JOIN companies c ON c.id=u.company_id AND c.active=1 WHERE u.id=? AND p.id=? AND u.active=1 AND u.role='client'",[$recipient,$plant]);$f=$_FILES['file']??null;$cfg=C::config();if(!$r||$title===''||!$f||$f['error']!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name'])||$f['size']<1||$f['size']>$cfg['max_upload_bytes'])fail('Controlla destinatario, impianto e dimensione del file.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['application/pdf','image/png','image/jpeg','text/plain','application/zip','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'];if(!in_array($mime,$allowed,true))fail('Tipo di file non consentito.');$dir=$cfg['storage_path'];if(!is_dir($dir)||!is_writable($dir)||realpath($dir)===false||str_starts_with(realpath($dir),realpath(__DIR__)))fail('Archivio privato non configurato correttamente.',503);$capacity=$cfg['capacity_bytes'];if($capacity!==null){$used=(int)C::row('SELECT COALESCE(SUM(bytes),0) n FROM documents WHERE deleted_at IS NULL')['n'];if($used+$f['size']>$capacity)fail('Spazio insufficiente per questo documento.',507);} $key=bin2hex(random_bytes(32));$dest=rtrim($dir,'/').'/'.$key;if(!move_uploaded_file($f['tmp_name'],$dest))fail('Caricamento non riuscito.',503);chmod($dest,0600);try{C::db()->beginTransaction();C::exec('INSERT INTO documents(company_id,plant_id,recipient_id,title,original_name,storage_key,mime,bytes,sha256,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)',[$r['company_id'],$plant,$recipient,$title,cleanFilename($f['name']),$key,$mime,$f['size'],hash_file('sha256',$dest),$u['id']]);$id=