 if($action==='revoke'){$id=(int)($_POST['id']??0);if(!C::row('SELECT id FROM documents WHERE id=? AND deleted_at IS NULL',[$id]))fail('Documento non trovato.',404);C::exec('UPDATE documents SET revoked_at=UTC_TIMESTAMP() WHERE id=? AND revoked_at IS NULL',[$id]);C::audit((int)$u['id'],'document_revoked',$id);C::go('/?saved=1');}
