 if($tab==='events'&&$u['role']==='admin'){$events=C::all('SELECT e.*,d.title,u.first_name,u.last_name,u.email,c.name company,p.name plant FROM download_events e JOIN documents d ON d.id=e.document_id JOIN users u ON u.id=e.user_id JOIN companies c ON c.id=d.company_id JOIN plants p ON p.id=d.plant_id ORDER BY e.started_at DESC LIMIT 300');$body.='<section class="card"><h2>Download registrati</h2><p>La data indica l’avvio della trasmissione dal server, non la conferma del salvataggio sul dispositivo.</p><div class="scroll"><table><thead><tr><th>Documento</th><th>Persona</th><th>Azienda / impianto</th><th>Data e ora (Italia)</th></tr></thead><tbody>';foreach($events as $e)$body.='<tr><td>'.C::h($e['title']).'</td><td>'.C::h($e['first_name'].' '.$e['last_name']).'<small>'.C::h($e['email']).'</small></td><td>'.C::h($e['company'].' / '.$e['plant']).'</td><td>'.C::date($e['started_at']).'</td></tr>';$body.='</tbody></table></div></section>';}
